DO $$
DECLARE
  f RECORD;
  fix RECORD;
BEGIN
  IF EXISTS (SELECT 1 FROM emission_factor_changes WHERE batch_label = 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien') THEN
    RETURN;
  END IF;

  FOR f IN SELECT * FROM emission_factors WHERE id IN ('elec_algeria', 'elec_br', 'elec_cameroon', 'elec_civ', 'elec_cn', 'elec_congo', 'elec_congo_rdc', 'elec_de', 'elec_ethiopia', 'elec_eu', 'elec_gabon', 'elec_guinea', 'elec_in', 'elec_kenya', 'elec_morocco', 'elec_nigeria', 'elec_senegal', 'elec_south_africa', 'elec_tunisia', 'elec_uk', 'elec_us', 'elec_world_avg') AND status = 'active' LOOP
    UPDATE emission_factors SET status = 'retired', updated_at = NOW() WHERE id = f.id;
    INSERT INTO emission_factor_changes (factor_id, action, before, after, batch_label)
    VALUES (f.id, 'retired', jsonb_build_object('status', 'active'), jsonb_build_object('status', 'retired'), 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien');
  END LOOP;

  FOR fix IN SELECT * FROM (VALUES ('r134a', 1430::numeric, 1300::numeric), ('r410a', 2088::numeric, 1924::numeric), ('r404a', 3922::numeric, 3943::numeric), ('r407c', 1774::numeric, 1624::numeric), ('r32', 675::numeric, 677::numeric)) AS v(id, old_value, new_value) LOOP
    UPDATE emission_factors
    SET factor_total = fix.new_value, factor_combustion = fix.new_value, source = 'IPCC AR5 (2014)', updated_at = NOW()
    WHERE id = fix.id AND factor_total = fix.old_value;
    IF FOUND THEN
      INSERT INTO emission_factor_changes (factor_id, action, before, after, batch_label)
      VALUES (fix.id, 'updated', jsonb_build_object('factor_total', fix.old_value), jsonb_build_object('factor_total', fix.new_value), 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien');
    END IF;
  END LOOP;

  UPDATE emission_factors SET unit = 'kgCO2eq/tonne.km', name_fr = 'Fret aérien (par tonne.km)', updated_at = NOW()
  WHERE id = 'air_freight' AND unit = 'kgCO2eq/km';
  IF FOUND THEN
    INSERT INTO emission_factor_changes (factor_id, action, before, after, batch_label)
    VALUES ('air_freight', 'updated', jsonb_build_object('unit', 'kgCO2eq/km'), jsonb_build_object('unit', 'kgCO2eq/tonne.km'), 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien');
  END IF;

  -- Marker: the batch is recorded even when nothing above applied (e.g. factors already edited by an admin)
  IF NOT EXISTS (SELECT 1 FROM emission_factor_changes WHERE batch_label = 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien') THEN
    INSERT INTO emission_factor_changes (factor_id, action, before, after, batch_label)
    VALUES ('elec_ember_gabon', 'created', NULL, jsonb_build_object('note', 'lot appliqué'), 'Migration 2026-10 : électricité Ember, PRG AR5, unité fret aérien');
  END IF;
END $$;
